contract InvMutTest {
    C c;

    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address to, uint256 value) public {
        require(to != address(0));
        require(value <= c.balanceOf(address(this)));

        uint256 totalBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 fromBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 toBefore = c.balanceOf(to); if (__ESBMC_reverted()) return;

        bool reverted;
        c.transfer(to, value); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 totalAfter = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 fromAfter = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 toAfter = c.balanceOf(to); if (__ESBMC_reverted()) return;

        assert(
            reverted
            ? (fromAfter == fromBefore && toAfter == toBefore && totalAfter == totalBefore)
            : (fromAfter == fromBefore - value && toAfter == toBefore + value && totalAfter == totalBefore)
        );
    }

    receive() external payable {}
}

